#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testMergeBalanceAccount();

void testMergeBalanceAccount() {
  ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict{
      {std::string("id"), std::string("sampleexchange")},
  });
  // isolated margin hands one account per market; the same code across two
  // markets is summed into a single flat entry, missing fields stay undefined.
  // the helper returns the merged dict and callers reassign it: PHP arrays are
  // passed by value, so mutating the argument alone is invisible there.
  // the local is seeded from the helper itself so the Go port infers the
  // helper's own return type instead of a map literal it cannot assign back to
  ccxt::any btcAccount = exchange.account();
  ::setValue(btcAccount, std::string("free"), std::string("1"));
  ::setValue(btcAccount, std::string("used"), std::string("0.5"));
  ::setValue(btcAccount, std::string("debt"), std::string("0.1"));
  ccxt::any result = exchange.mergeBalanceAccount(
      ccxt::dict{}, std::string("BTC"), btcAccount);
  assertTrue(isEqual(exchange.safeString(::getValue(result, std::string("BTC")),
                                         std::string("free")),
                     std::string("1")));
  ccxt::any btcAccount2 = exchange.account();
  ::setValue(btcAccount2, std::string("free"), std::string("2"));
  ::setValue(btcAccount2, std::string("used"), std::string("0.25"));
  ::setValue(btcAccount2, std::string("total"), std::string("2.25"));
  result =
      exchange.mergeBalanceAccount(result, std::string("BTC"), btcAccount2);
  assertTrue(isEqual(exchange.safeString(::getValue(result, std::string("BTC")),
                                         std::string("free")),
                     std::string("3")));
  assertTrue(isEqual(exchange.safeString(::getValue(result, std::string("BTC")),
                                         std::string("used")),
                     std::string("0.75")));
  assertTrue(isEqual(exchange.safeString(::getValue(result, std::string("BTC")),
                                         std::string("total")),
                     std::string("2.25")));
  assertTrue(isEqual(exchange.safeString(::getValue(result, std::string("BTC")),
                                         std::string("debt")),
                     std::string("0.1")));
  ccxt::any usdtAccount = exchange.account();
  ::setValue(usdtAccount, std::string("free"), std::string("5"));
  result =
      exchange.mergeBalanceAccount(result, std::string("USDT"), usdtAccount);
  assertTrue(
      isEqual(exchange.safeString(::getValue(result, std::string("USDT")),
                                  std::string("free")),
              std::string("5")));
  assertTrue(
      isEqual(exchange.safeString(::getValue(result, std::string("USDT")),
                                  std::string("used")),
              ccxt::any{}));
  ccxt::any keys = getObjectKeys(result);
  assertTrue(isEqual(getArrayLength(keys), 2));
  // the merged dict is a regular safeBalance input. safeBalance parses to a
  // number, and each port spells that number differently (JS "3", PHP "3.0"),
  // so assert on the parsed value rather than on its string form
  ccxt::any balance = exchange.safeBalance(result);
  assertTrue(
      isEqual(exchange.safeNumber(::getValue(balance, std::string("BTC")),
                                  std::string("free")),
              exchange.parseNumber(std::string("3"))));
  assertTrue(
      isEqual(exchange.safeNumber(::getValue(balance, std::string("free")),
                                  std::string("USDT")),
              exchange.parseNumber(std::string("5"))));
  assertTrue(
      isEqual(exchange.safeNumber(::getValue(balance, std::string("debt")),
                                  std::string("BTC")),
              exchange.parseNumber(std::string("0.1"))));
}
